{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "The closest experimental analogue (C05, Morgan 0.355) is a large peptide-like kappa agonist with an N-terminal pentylamine and multiple amide bonds; its measured brain/plasma ratio was 0.001, directly indicating poor BBB penetration that transfers to the query's similar peptide/amine architecture.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "C08, a closely related pentylamine peptidomimetic with a pyridylpiperazine amide, showed low brain uptake after IV administration in rat, supporting poor CNS access for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "C03, a piperidine/pyridylpiperazine benzolactam, had brain/plasma AUC of only 6.7% in mouse, a low-permeability phenotype consistent with the query's large polar structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "C06 (lisdexamfetamine), a primary-amine-containing amide prodrug, was not detected in rat brain after oral dosing, reinforcing that N-terminal primary amine/peptide-like motifs do not confer meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "C01, a large endogenous peptide, was undetectable in human CSF, supporting that high-molecular-weight peptide-like molecules generally fail to achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "C09, a smaller pyridylpiperazine amide, was detected in mouse brain after 2 h, showing that the pyridylpiperazine group is not an absolute BBB barrier; however, its much lower molecular weight and polarity limit transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C04"],
      "claim": "C04 (galmic, MW 984) crossed the BBB and suppressed status epilepticus, demonstrating that very large molecules can sometimes access CNS; its low similarity and different scaffold reduce relevance to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted fail: the query is a large, highly polar, ionizable peptidomimetic; the closest and multiple related experimental analogues show poor brain penetration/CSF exposure, and the few permeable analogues are structurally distant.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or uptake measurement exists for the query molecule.",
    "No experimental P-gp/BCRP efflux data are available for the query.",
    "Morgan similarities to the evidence molecules are low (<0.36), limiting quantitative transfer.",
    "A few large or pyridylpiperazine-containing molecules do cross the BBB, so the fail prediction carries residual uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

